    public static IEnumerable<object[]> Probes() => Cases.Select(c => new object[] { c.Name, c.Script });
    [Theory]
    [MemberData(nameof(Probes))]
    public void MatchesVfp9(string name, string script)
        => Assert.Equal(Expected[name], MicroVfpNumericScaleReviewSupport.Run(script));
